func cloneFloats(values []float64) []float64 {
	return slices.Clone(values)
}

// NOTE: The CSV fixtures consumed by these tests (test_data/pivot_points/output_*.csv)
// were generated by a Python script using pandas to compute reference pivot levels from input_data2.csv.

func TestPivotPointsStandardDailyDefault(t *testing.T) {
	candles, _ := readCandles("test_data/input_data2.csv")
	expectedParsedData, _ := readData("test_data/pivot_points/output_standard_daily.csv", []int{1, 2, 3, 4, 5, 6, 7}, 4)
	indicator, _ := talive.NewPivotPoints()
	result := make([][]float64, 7)
	for i := range result {
		result[i] = make([]float64, len(candles))
	}
	for i, candle := range candles {
		res := indicator.Next(candle)
		for j := 0; j < 7; j++ {
			result[j][i] = roundFloat(res[j], 4)
		}
	}
	labels := []string{"P", "R1", "R2", "R3", "S1", "S2", "S3"}
	for j, label := range labels {
		if !reflect.DeepEqual(result[j], expectedParsedData[j]) {
			t.Fatalf("[PivotPoints Standard/Daily] %s values didn't match %v", label, difference(result[j], expectedParsedData[j]))
		}
	}
}

